#[cfg(feature="mesh-import")]
use super::mesh::Mesh;
/// No material file I/O callback. OBJ triangles only, explicit rejection before
/// parser triangulation so concave/line/point geometry is never misrepresented.
#[cfg(feature="mesh-import")]
pub fn obj(text:&str)->Result<Vec<Mesh>,String>{if text.len()>16*1024*1024{return Err("OBJ max16MiB".into());}for line in text.lines(){let tokens:Vec<_>=line.split('#').next().unwrap_or("").split_whitespace().collect();if tokens.first()==Some(&"f")&&tokens.len()!=4{return Err("initial OBJ importer requires triangular faces".into());}if tokens.first()==Some(&"l")||tokens.first()==Some(&"p")||tokens.first()==Some(&"mtllib"){return Err("line/point/external materials unsupported in initial importer".into());}}let (models,_)=tobj::load_obj_buf(&mut std::io::Cursor::new(text),&tobj::LoadOptions{triangulate:false,single_index:true,..Default::default()},|_|Err(tobj::LoadError::OpenFileFailed)).map_err(|e|e.to_string())?;models.into_iter().map(|model|{let m=model.mesh;if !m.normals.is_empty()||!m.texcoords.is_empty(){return Err("initial position-only importer rejects normal/UV buffers rather than losing them".into());}let mesh=Mesh{positions:m.positions.chunks_exact(3).map(|p|[p[0] as f64,p[1] as f64,p[2] as f64]).collect(),indices:m.indices.chunks_exact(3).map(|i|[i[0],i[1],i[2]]).collect()};mesh.validate()?;Ok(mesh)}).collect()}
/// GLB only, embedded buffer only. Hierarchy/material/UV/skin/morph unsupported
/// at this scaffold stage and rejected. This prevents silent semantic loss.
#[cfg(feature="mesh-import")]
pub fn glb(bytes:&[u8])->Result<Vec<Mesh>,String>{if bytes.len()>16*1024*1024{return Err("GLB max16MiB".into());}let g=gltf::Gltf::from_slice(bytes).map_err(|e|e.to_string())?;let blob=g.blob.as_ref().ok_or("initial glTF importer requires embedded GLB")?;for b in g.document.buffers(){if !matches!(b.source(),gltf::buffer::Source::Bin){return Err("external/data URI buffer unsupported".into());}}if g.document.nodes().next().is_some()||g.document.materials().next().is_some()||g.document.skins().next().is_some()||g.document.animations().next().is_some(){return Err("initial buffer-only GLB importer rejects scene nodes/materials/skins/animation; hierarchy integration pending".into());}let mut out=Vec::new();for m in g.document.meshes(){for p in m.primitives(){if p.mode()!=gltf::mesh::Mode::Triangles||p.morph_targets().next().is_some()||p.attributes().any(|(s,_)|s!=gltf::Semantic::Positions){return Err("initial GLB importer supports position-only triangles, no morphs".into());}let reader=p.reader(|b|if b.index()==0{Some(blob.as_slice())}else{None});let positions=reader.read_positions().ok_or("positions missing")?.map(|p|p.map(|v|v as f64)).collect::<Vec<_>>();let indices=reader.read_indices().map(|r|r.into_u32().collect::<Vec<_>>()).unwrap_or_else(||(0..positions.len() as u32).collect());if indices.len()%3!=0{return Err("triangle index count not divisible3".into());}let mesh=Mesh{positions,indices:indices.chunks_exact(3).map(|i|[i[0],i[1],i[2]]).collect()};mesh.validate()?;out.push(mesh);}}if out.is_empty(){return Err("no supported meshes".into());}Ok(out)}
